-- READ-ONLY aggregate; fixed UTC gap episodes from the frozen interval-aware catalog.
SELECT 'eu' AS archive, 28 AS gap_count, COUNT(DISTINCT gap_id) AS gaps_with_any_rows, 28-COUNT(DISTINCT gap_id) AS gaps_without_rows, COUNT(*) AS source_rows, COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1264189800 AND `dateTime`<1264196700 THEN 1 WHEN `dateTime`>1265658600 AND `dateTime`<1265665500 THEN 2 WHEN `dateTime`>1267117500 AND `dateTime`<1267126200 THEN 3 WHEN `dateTime`>1267133100 AND `dateTime`<1267140300 THEN 4 WHEN `dateTime`>1268089500 AND `dateTime`<1268096100 THEN 5 WHEN `dateTime`>1268590500 AND `dateTime`<1268599500 THEN 6 WHEN `dateTime`>1269203100 AND `dateTime`<1269221700 THEN 7 WHEN `dateTime`>1271607600 AND `dateTime`<1271614800 THEN 8 WHEN `dateTime`>1275230100 AND `dateTime`<1275237600 THEN 9 WHEN `dateTime`>1275593400 AND `dateTime`<1275605700 THEN 10 WHEN `dateTime`>1276377900 AND `dateTime`<1276397100 THEN 11 WHEN `dateTime`>1276794900 AND `dateTime`<1276801500 THEN 12 WHEN `dateTime`>1277986500 AND `dateTime`<1277997900 THEN 13 WHEN `dateTime`>1278514500 AND `dateTime`<1278541500 THEN 14 WHEN `dateTime`>1278852300 AND `dateTime`<1278864000 THEN 15 WHEN `dateTime`>1280078100 AND `dateTime`<1280085000 THEN 16 WHEN `dateTime`>1280091000 AND `dateTime`<1280099100 THEN 17 WHEN `dateTime`>1281032100 AND `dateTime`<1281043800 THEN 18 WHEN `dateTime`>1281292200 AND `dateTime`<1281307800 THEN 19 WHEN `dateTime`>1281742800 AND `dateTime`<1281752700 THEN 20 WHEN `dateTime`>1281785400 AND `dateTime`<1281792900 THEN 21 WHEN `dateTime`>1281981600 AND `dateTime`<1281987900 THEN 22 WHEN `dateTime`>1285695600 AND `dateTime`<1285716900 THEN 23 WHEN `dateTime`>1286637600 AND `dateTime`<1286642700 THEN 24 WHEN `dateTime`>1287438600 AND `dateTime`<1287453600 THEN 25 WHEN `dateTime`>1288218600 AND `dateTime`<1288225500 THEN 26 WHEN `dateTime`>1289602500 AND `dateTime`<1289609100 THEN 27 WHEN `dateTime`>1292068800 AND `dateTime`<1292075700 THEN 28 ELSE NULL END AS gap_id, `outTemp`, `outHumidity`, `rain`, `rainRate`, `windSpeed`, `windGust`, `barometer` FROM `pocasi-loucka.eu`.`archive` WHERE (`dateTime`>1264189800 AND `dateTime`<1264196700) OR (`dateTime`>1265658600 AND `dateTime`<1265665500) OR (`dateTime`>1267117500 AND `dateTime`<1267126200) OR (`dateTime`>1267133100 AND `dateTime`<1267140300) OR (`dateTime`>1268089500 AND `dateTime`<1268096100) OR (`dateTime`>1268590500 AND `dateTime`<1268599500) OR (`dateTime`>1269203100 AND `dateTime`<1269221700) OR (`dateTime`>1271607600 AND `dateTime`<1271614800) OR (`dateTime`>1275230100 AND `dateTime`<1275237600) OR (`dateTime`>1275593400 AND `dateTime`<1275605700) OR (`dateTime`>1276377900 AND `dateTime`<1276397100) OR (`dateTime`>1276794900 AND `dateTime`<1276801500) OR (`dateTime`>1277986500 AND `dateTime`<1277997900) OR (`dateTime`>1278514500 AND `dateTime`<1278541500) OR (`dateTime`>1278852300 AND `dateTime`<1278864000) OR (`dateTime`>1280078100 AND `dateTime`<1280085000) OR (`dateTime`>1280091000 AND `dateTime`<1280099100) OR (`dateTime`>1281032100 AND `dateTime`<1281043800) OR (`dateTime`>1281292200 AND `dateTime`<1281307800) OR (`dateTime`>1281742800 AND `dateTime`<1281752700) OR (`dateTime`>1281785400 AND `dateTime`<1281792900) OR (`dateTime`>1281981600 AND `dateTime`<1281987900) OR (`dateTime`>1285695600 AND `dateTime`<1285716900) OR (`dateTime`>1286637600 AND `dateTime`<1286642700) OR (`dateTime`>1287438600 AND `dateTime`<1287453600) OR (`dateTime`>1288218600 AND `dateTime`<1288225500) OR (`dateTime`>1289602500 AND `dateTime`<1289609100) OR (`dateTime`>1292068800 AND `dateTime`<1292075700)) q;
